function encodeRFC3986(value) {
  return encodeURIComponent(value).replace(/[!'()*]/g, function (character) {
    return "%" + character.charCodeAt(0).toString(16).toUpperCase();
  });
}

function serializeColumns(columns) {
  if (
    columns === null ||
    typeof columns !== "object" ||
    (Object.getPrototypeOf(columns) !== Object.prototype &&
      Object.getPrototypeOf(columns) !== null) ||
    !Object.prototype.hasOwnProperty.call(columns, "keys") ||
    !Object.prototype.hasOwnProperty.call(columns, "values")
  ) {
    throw new TypeError();
  }

  var keys = columns.keys;
  var values = columns.values;

  if (!Array.isArray(keys) || !Array.isArray(values) || keys.length !== values.length) {
    throw new TypeError();
  }

  var pairs = new Array(keys.length);

  for (var i = 0; i < keys.length; i++) {
    if (
      !Object.prototype.hasOwnProperty.call(keys, i) ||
      !Object.prototype.hasOwnProperty.call(values, i) ||
      typeof keys[i] !== "string" ||
      (typeof values[i] !== "string" && values[i] !== null)
    ) {
      throw new TypeError();
    }

    var encodedName = encodeRFC3986(keys[i]);
    var encodedValue = encodeRFC3986(values[i] === null ? "" : values[i]);

    pairs[i] = {
      name: encodedName,
      value: encodedValue
    };
  }

  pairs.sort(function (a, b) {
    if (a.name < b.name) return -1;
    if (a.name > b.name) return 1;
    if (a.value < b.value) return -1;
    if (a.value > b.value) return 1;
    return 0;
  });

  return pairs.map(function (pair) {
    return pair.name + "=" + pair.value;
  }).join("&");
}
